function validate([s, c]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10,000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase English letters only.';
  if (typeof c !== 'string' || !/^[a-z]$/.test(c)) return 'c must be one lowercase letter.';
  if (!s.includes(c)) return 'c must appear in s.';
  return null;
}

