function shortestToChar(s, c) {
  const n = s.length;
  const answer = new Array(n);
  let prev = -1;
  let next = 0;
  while (s[next] !== c) {
    next++;
  }
  for (let i = 0; i < n; i++) {
    if (i === next) {
      prev = i;
      next = i + 1;
      while (next < n && s[next] !== c) {
        next++;
      }
    }
    const toPrev = prev === -1 ? Infinity : i - prev;
    const toNext = next === n ? Infinity : next - i;
    answer[i] = Math.min(toPrev, toNext);
  }
  return answer;
}

