function shortestToChar(s, c) {
  const result = [];
  for (let i = 0; i < s.length; i++) {
    let best = Infinity;
    for (let j = 0; j < s.length; j++) {
      if (s[j] === c) best = Math.min(best, Math.abs(i - j));
    }
    result.push(best);
  }
  return result;
}

