function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const style = rand();
  const pool = style < 0.4 ? 'ab' : style < 0.7 ? 'abc' : 'abcdefghijklmnopqrstuvwxyz';
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(pool[Math.floor(rand() * pool.length)]);
  let c;
  if (rand() < 0.3) {
    // A single occurrence of a letter that appears nowhere else.
    c = 'z';
    for (let i = 0; i < n; i++) if (chars[i] === 'z') chars[i] = 'y';
    chars[Math.floor(rand() * n)] = 'z';
  } else {
    c = chars[Math.floor(rand() * n)];
  }
  return [chars.join(''), c];
}
